export default function (pi) {
  let dumps = 0;
  pi.registerTool({
    name: "dump", label: "Dump", description: "Oversized local output",
    parameters: { type: "object", properties: {} },
    async execute() {
      const sizes = [350000];
      const chars = sizes[Math.min(dumps++, sizes.length - 1)];
      return { content: [{ type: "text", text: `DUMP_HEAD ${"x".repeat(chars)} DUMP_TAIL` }, ...[]], details: {}, terminate: false };
    },
  });
}

export default function (pi) {
  pi.on("session_before_compact", () => { pi.appendEntry("compact-hook-seen", {}); });
  pi.on("turn_end", (event) =>
    event.toolResults.some((result) => result.toolName === "dump")
      ? { entries: [...event.entries, { type: "custom_message", customType: "coordination", content: "NEW_TURN_START_DRAFT", display: true }] }
      : undefined);
}
